    "Pelialue: vaunu täynnä lippupalloja": "Spielfeld: ein Waggon voller Flaggenbälle",
    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "<b>Ziele</b> mit der Maus oder dem Finger. Je weiter du zeigst, desto stärker fliegt der Ball.",
    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "<b>Schieß</b> per Klick oder indem du den Finger vom Bildschirm hebst.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "Ein sanfter Schuss legt den Ball vorsichtig ab, ein harter Schuss <b>schubst und quetscht</b> die anderen.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "In den Waggonwänden sind zwei Knöpfe. Berühren Bälle <b>beide Knöpfe</b> gleichzeitig, ist das Spiel vorbei.",
    "Joka <b>40 000 pisteellä</b> saat heilautuksen, joka ravistaa vaunua ja sekoittaa pallot.": "Alle <b>40.000 Punkte</b> bekommst du ein Schütteln, das den Waggon rüttelt und die Bälle mischt.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja harvinaisia <b>sydämiä</b>, niin saat bonuspisteitä.": "Triff die <b>Sterne</b> und seltenen <b>Herzen</b>, die oben durch den Waggon fliegen, für Bonuspunkte.",
    "Saavutuksista saat <b>pokaaleja</b> vaunun pohjan hyllyille. Tartu pokaaliin sormella ja <b>heitä</b> sitä ympäri vaunua!": "Erfolge bringen dir <b>Pokale</b> auf die Regale am Waggonboden. Pack einen Pokal mit dem Finger und <b>wirf</b> ihn durch den Waggon!",
