    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Collect as many points as you can and beat the stages by merging the two biggest balls. The game ends if the balls press both buttons at once.",
