    "Ei aikarajaa.": "Ajapiirangut pole.",
    "Pisteet ja heilautukset säilyvät, kun siirryt seuraavalle tasolle.": "Punktid ja raputused jäävad alles, kui liigud järgmisele tasemele.",
    "Avautuu, kun läpäiset tason {0}.": "Avaneb, kui läbid taseme {0}.",
    "Selvä!": "Selge!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Kogu võimalikult palju punkte ja läbi tasemed, ühendades kaks suurimat palli. Mäng lõpeb, kui pallid vajutavad mõlemat nuppu korraga.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Kogu kahe minutiga nii palju punkte kui jõuad. Nuppude tõttu ei saa kaotada.",
    "Saa {0} mahdollisimman vähillä laukauksilla. Kaikilla on sama pallojärjestys, ja haaste vaihtuu joka päivä klo 15.": "Saa {0} võimalikult väheste lasudega. Kõigil on sama pallide järjekord ja väljakutse vahetub iga päev kell 15.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Mitte midagi, lihtsalt lõõgastu. Punkte ei loeta ja kaotada ei saa.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Kogu võimalikult palju punkte, kui raskusjõu suund muutub iga paari sekundi järel. Mäng lõpeb, kui pallid vajutavad mõlemat nuppu.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "Täida {1} missiooni järjest. Igal missioonil on oma eesmärk, näiteks teatud pall piiratud lasudega või punktid ajapiirangu sees.",
