    "Yritä uudelleen saada {0}. Pallojärjestys pysyy samana, kunnes uusi haaste alkaa klo 15.": "Réessaie d'obtenir {0}. L'ordre des boules reste le même jusqu'au nouveau défi à 15 h, heure finlandaise.",
