    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "<b>Célozz</b> egérrel vagy ujjal. Minél messzebbre mutatsz, annál erősebben repül a golyó.",
