    "Ammu sydänpalloja vaunuun. Kaksi samaa sydäntä yhdistyy isommaksi, vaaleanpunaisesta aina kultaiseen sydämeen asti.": "Lőj szívgolyókat a vagonba. Két egyforma szív egy nagyobbá olvad össze, a rózsaszíntől egészen az aranyszívig.",
    "Ammu laskupalloja vaunuun. Kaksi samaa laskua yhdistyy vaikeammaksi, yhteenlaskusta aina matriisiin asti.": "Lőj feladatgolyókat a vagonba. Két egyforma feladat egy nehezebbé olvad össze, az összeadástól egészen a mátrixig.",
