    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "<b>Mira</b> con il mouse o con il dito. Più lontano punti, più forte vola la pallina.",
    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "<b>Spara</b> facendo clic o sollevando il dito dallo schermo.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "Un tiro leggero posa la pallina con delicatezza, un tiro forte <b>spinge e schiaccia</b> le altre.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "Sulle pareti del vagone ci sono due pulsanti. Se le palline toccano <b>entrambi i pulsanti</b> insieme, la partita finisce.",
    "Joka <b>40 000 pisteellä</b> saat heilautuksen, joka ravistaa vaunua ja sekoittaa pallot.": "Ogni <b>40.000 punti</b> ricevi una scossa che fa tremare il vagone e mescola le palline.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja harvinaisia <b>sydämiä</b>, niin saat bonuspisteitä.": "Colpisci le <b>stelle</b> e i rari <b>cuori</b> che volano in cima al vagone per ottenere punti bonus.",
    "Saavutuksista saat <b>pokaaleja</b> vaunun pohjan hyllyille. Tartu pokaaliin sormella ja <b>heitä</b> sitä ympäri vaunua!": "Gli obiettivi ti danno <b>trofei</b> sugli scaffali in fondo al vagone. Afferra un trofeo con il dito e <b>lancialo</b> per il vagone!",
