    "Selvä!": "Capito!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Raccogli più punti possibile e supera i livelli unendo le due palle più grandi. La partita finisce se le palle premono entrambi i pulsanti insieme.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Raccogli più punti che puoi in due minuti. Non puoi perdere per i pulsanti.",
    "Saa {0} mahdollisimman vähillä laukauksilla. Kaikilla on sama pallojärjestys, ja haaste vaihtuu joka päivä klo 15.": "Ottieni {0} con meno tiri possibile. Tutti hanno lo stesso ordine di palle, e la sfida cambia ogni giorno alle 15.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Niente, solo relax. Non si contano punti e non puoi perdere.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Raccogli più punti possibile mentre la direzione della gravità cambia ogni pochi secondi. La partita finisce se le palle premono entrambi i pulsanti.",
