    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "<b>Tēmē</b> ar peli vai pirkstu. Jo tālāk norādi, jo stiprāk bumba lido.",
    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "<b>Šauj</b>, noklikšķinot vai paceļot pirkstu no ekrāna.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "Viegls šāviens noliek bumbu uzmanīgi, stiprs šāviens <b>grūž un saspiež</b> citas.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "Vagona sienās ir divas pogas. Ja bumbas vienlaikus pieskaras <b>abām pogām</b>, spēle beidzas.",
    "Joka <b>40 000 pisteellä</b> saat heilautuksen, joka ravistaa vaunua ja sekoittaa pallot.": "Ik pēc <b>40 000 punktiem</b> tu saņem kratīšanu, kas sakrata vagonu un sajauc bumbas.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja harvinaisia <b>sydämiä</b>, niin saat bonuspisteitä.": "Šauj pa <b>zvaigznēm</b> un retajām <b>sirdīm</b>, kas lido vagona augšā, lai iegūtu bonusa punktus.",
    "Saavutuksista saat <b>pokaaleja</b> vaunun pohjan hyllyille. Tartu pokaaliin sormella ja <b>heitä</b> sitä ympäri vaunua!": "Par sasniegumiem saņem <b>kausus</b> uz plauktiem vagona apakšā. Satver kausu ar pirkstu un <b>met</b> to pa vagonu!",
