    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "<b>Trage</b> făcând clic sau ridicând degetul de pe ecran.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "O lovitură ușoară așază bila cu grijă, una puternică <b>împinge și strivește</b> celelalte bile.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "Pe pereții vagonului sunt două butoane. Dacă bilele ating <b>ambele butoane</b> în același timp, jocul se termină.",
    "Joka <b>40 000 pisteellä</b> saat heilautuksen, joka ravistaa vaunua ja sekoittaa pallot.": "La fiecare <b>40.000 de puncte</b> primești o scuturare care zgâlțâie vagonul și amestecă bilele.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja harvinaisia <b>sydämiä</b>, niin saat bonuspisteitä.": "Trage în <b>stelele</b> și rarele <b>inimi</b> care zboară în partea de sus a vagonului pentru puncte bonus.",
