    "Jos aikaraja ylittyy, peli päättyy.": "Если лимит времени истёк, игра заканчивается.",
    "Ei aikarajaa.": "Без лимита времени.",
    "Pisteet ja heilautukset säilyvät, kun siirryt seuraavalle tasolle.": "Очки и встряски сохраняются, когда переходишь на следующий уровень.",
    "Avautuu, kun läpäiset tason {0}.": "Откроется, когда пройдёшь уровень {0}.",
    "Selvä!": "Понятно!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Набери как можно больше очков и проходи уровни, сливая два самых больших шара. Игра заканчивается, если шары одновременно давят на обе кнопки.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Набери за две минуты столько очков, сколько успеешь. Из-за кнопок проиграть нельзя.",
    "Saa {0} mahdollisimman vähillä laukauksilla. Kaikilla on sama pallojärjestys, ja haaste vaihtuu joka päivä klo 15.": "Получи {0} за как можно меньшее число выстрелов. У всех одинаковый порядок шаров, а испытание меняется каждый день в 15:00.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Ничего, просто отдыхай. Очки не считаются, и проиграть нельзя.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Набери как можно больше очков, пока направление гравитации меняется каждые несколько секунд. Игра заканчивается, если шары давят на обе кнопки.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "Выполни {1} миссий по порядку. У каждой миссии своя цель, например определённый шар за ограниченное число выстрелов или очки в пределах лимита времени.",
