    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "Fareyle veya parmağınla <b>nişan al</b>. Ne kadar uzağı gösterirsen top o kadar güçlü uçar.",
