    "Selvä!": "Anladım!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Olabildiğince çok puan topla ve en büyük iki topu birleştirerek seviyeleri geç. Toplar iki düğmeye aynı anda basarsa oyun biter.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "İki dakikada yetişebildiğin kadar puan topla. Düğmeler yüzünden kaybedemezsin.",
    "Saa {0} mahdollisimman vähillä laukauksilla. Kaikilla on sama pallojärjestys, ja haaste vaihtuu joka päivä klo 15.": "{0} topunu olabildiğince az atışla elde et. Herkes aynı top sırasını alır ve meydan okuma her gün saat 15’te değişir.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Hiçbir şey, sadece rahatla. Puan sayılmaz ve kaybedemezsin.",
