    "<b>Tähtää</b> hiirellä tai sormella. Mitä kauemmas osoitat, sitä kovempaa pallo lentää.": "<b>Цілься</b> мишею або пальцем. Що далі вказуєш, то сильніше летить куля.",
    "<b>Ammu</b> klikkaamalla tai nostamalla sormen ruudulta.": "<b>Стріляй</b> клацанням або піднявши палець з екрана.",
    "Kevyt laukaus laskee pallon varovasti, kova laukaus <b>tönii ja litistää</b> muita.": "Легкий постріл обережно кладе кулю, сильний <b>штовхає і сплющує</b> інші.",
    "Vaunun seinissä on kaksi nappia. Jos pallot koskettavat <b>molempia nappeja</b> yhtä aikaa, peli päättyy.": "На стінах вагона дві кнопки. Якщо кулі одночасно торкнуться <b>обох кнопок</b>, гра закінчиться.",
    "Joka <b>40 000 pisteellä</b> saat heilautuksen, joka ravistaa vaunua ja sekoittaa pallot.": "Кожні <b>40 000 очок</b> ти отримуєш струс, який трусить вагон і перемішує кулі.",
    "Ammu vaunun yläosassa lentäviä <b>tähtiä</b> ja harvinaisia <b>sydämiä</b>, niin saat bonuspisteitä.": "Стріляй у <b>зірки</b> та рідкісні <b>серця</b>, що літають угорі вагона, щоб отримати бонусні очки.",
    "Saavutuksista saat <b>pokaaleja</b> vaunun pohjan hyllyille. Tartu pokaaliin sormella ja <b>heitä</b> sitä ympäri vaunua!": "За досягнення ти отримуєш <b>кубки</b> на полицях унизу вагона. Схопи кубок пальцем і <b>кинь</b> його по вагону!",
