    "Pisteet ja heilautukset säilyvät, kun siirryt seuraavalle tasolle.": "Очки та струшування зберігаються, коли переходиш на наступний рівень.",
    "Avautuu, kun läpäiset tason {0}.": "Відкриється, коли пройдеш рівень {0}.",
    "Selvä!": "Зрозуміло!",
    "Kerää mahdollisimman paljon pisteitä ja läpäise tasot yhdistämällä kaksi suurinta palloa. Peli päättyy, jos pallot painavat molempia nappeja yhtä aikaa.": "Збери якомога більше очок і проходь рівні, зливаючи дві найбільші кульки. Гра закінчується, якщо кульки одночасно тиснуть на обидві кнопки.",
    "Kerää kahdessa minuutissa niin paljon pisteitä kuin ehdit. Nappeihin ei voi hävitä.": "Збери за дві хвилини стільки очок, скільки встигнеш. Через кнопки програти не можна.",
    "Saa {0} mahdollisimman vähillä laukauksilla. Kaikilla on sama pallojärjestys, ja haaste vaihtuu joka päivä klo 15.": "Здобудь {0} якомога меншою кількістю пострілів. Усі мають однаковий порядок кульок, а виклик змінюється щодня о 15:00.",
    "Ei mitään, vain rentoutumista. Pisteitä ei lasketa, eikä peliä voi hävitä.": "Нічого, просто відпочивай. Очки не рахуються, і програти не можна.",
    "Kerää mahdollisimman paljon pisteitä, kun painovoiman suunta vaihtuu muutaman sekunnin välein. Peli päättyy, jos pallot painavat molempia nappeja.": "Збери якомога більше очок, поки напрямок гравітації змінюється кожні кілька секунд. Гра закінчується, якщо кульки тиснуть на обидві кнопки.",
    "Suorita {1} tehtävää järjestyksessä. Jokaisella tehtävällä on oma tavoitteensa, esimerkiksi tietty pallo rajatuilla laukauksilla tai pisteitä aikarajassa.": "Виконай {1} місій по черзі. Кожна місія має власну мету, наприклад певну кульку за обмежену кількість пострілів або очки в межах ліміту часу.",
